driverScript:
module.exports = {
  identified: false,
  password: '',

  onConnect: function(transport, config) {
    this.identified = false;
    this.password = config.password || '';
    engine.setStatus('connecting', 'Connecting to OBS WebSocket...');
  },

  onMessage: function(transport, messageText) {
    if (!messageText) return;
    var msg;
    try {
      msg = JSON.parse(messageText);
    } catch(e) {
      return;
    }

    var op = msg.op;
    var d = msg.d || {};

    if (op === 0) {
      var rpcVersion = d.rpcVersion || 1;
      var auth = d.authentication;
      var identifyData = {
        rpcVersion: rpcVersion,
        eventSubscriptions: 33
      };

      if (auth && this.password) {
        var challenge = auth.challenge;
        var salt = auth.salt;
        var secretHash = engine.crypto.sha256(this.password + salt);
        var secretBytes = engine.buffer.fromHex(secretHash);
        var secretBase64 = engine.crypto.base64Encode(secretBytes);
        var authHash = engine.crypto.sha256(secretBase64 + challenge);
        var authBytes = engine.buffer.fromHex(authHash);
        identifyData.authentication = engine.crypto.base64Encode(authBytes);
      }

      transport.sendJSON({ op: 1, d: identifyData });
      engine.setStatus('authenticating', 'Identifying with OBS...');
    } else if (op === 2) {
      this.identified = true;
      engine.setStatus('connected', 'Connected to OBS Studio');
      transport.sendJSON({
        op: 6,
        d: {
          requestType: 'GetCurrentProgramScene',
          requestId: 'init_scene'
        }
      });
      transport.sendJSON({
        op: 6,
        d: {
          requestType: 'GetStreamStatus',
          requestId: 'init_stream'
        }
      });
      transport.sendJSON({
        op: 6,
        d: {
          requestType: 'GetRecordStatus',
          requestId: 'init_record'
        }
      });
    } else if (op === 5) {
      var eventType = d.eventType;
      var eventData = d.eventData || {};

      if (eventType === 'CurrentProgramSceneChanged') {
        var scene = eventData.sceneName || '';
        engine.setVariable('obs_current_scene', scene);
      } else if (eventType === 'CurrentPreviewSceneChanged') {
        var scene = eventData.sceneName || '';
        engine.setVariable('obs_preview_scene', scene);
      } else if (eventType === 'StreamStateChanged') {
        engine.setVariable('obs_is_streaming', eventData.outputActive ? 'true' : 'false');
      } else if (eventType === 'RecordStateChanged') {
        engine.setVariable('obs_is_recording', eventData.outputActive ? 'true' : 'false');
      } else if (eventType === 'InputMuteStateChanged') {
        var inputName = eventData.inputName || '';
        engine.setVariable('obs_audio_' + inputName + '_muted', eventData.inputMuted ? 'true' : 'false');
      }
    } else if (op === 7) {
      var reqType = d.requestType;
      var resData = d.responseData || {};
      if (reqType === 'GetCurrentProgramScene' && resData.currentProgramSceneName) {
        engine.setVariable('obs_current_scene', resData.currentProgramSceneName);
      } else if (reqType === 'GetStreamStatus') {
        engine.setVariable('obs_is_streaming', resData.outputActive ? 'true' : 'false');
      } else if (reqType === 'GetRecordStatus') {
        engine.setVariable('obs_is_recording', resData.outputActive ? 'true' : 'false');
      }
    }
  },

  onAction: function(transport, actionId, params) {
    params = params || {};
    var rawAct = String(actionId || '').toLowerCase().trim();
    var act = rawAct.replace(/^\/+/, '');
    if (act.indexOf('/') !== -1) {
      act = act.split('/').pop();
    }
    act = act.replace(/^obs_/, '').replace(/^obs\./, '').replace(/^obs-/, '');
    var reqId = 'act_' + Date.now();

    if (act === 'get_current_scene' || act === 'get_scene') {
      var sc = engine.getVariable('obs_current_scene') || 'Unknown Scene';
      return 'Current Program Scene: ' + sc;
    } else if (act === 'get_stream_status' || act === 'get_stream') {
      var isStreaming = engine.getVariable('obs_is_streaming') || 'false';
      return 'Streaming: ' + isStreaming;
    } else if (act === 'get_record_status' || act === 'get_record') {
      var isRecording = engine.getVariable('obs_is_recording') || 'false';
      return 'Recording: ' + isRecording;
    } else if (act === 'get_input_mute_status' || act === 'get_input_mute' || act === 'get_mute') {
      var inputName = params.input_name || params.input || 'Mic/Aux';
      var isMuted = engine.getVariable('obs_audio_' + inputName + '_muted') || 'false';
      return inputName + ' Muted: ' + isMuted;
    }

    if (act === 'switch_scene' || act === 'set_scene' || act === 'scene') {
      var scene = params.scene_name || params.scene || params.value || params.param || '';
      transport.sendJSON({
        op: 6,
        d: {
          requestType: 'SetCurrentProgramScene',
          requestId: reqId,
          requestData: { sceneName: scene }
        }
      });
      engine.setVariable('obs_current_scene', scene);
      return 'Switched scene to ' + scene;
    } else if (act === 'toggle_stream' || act === 'stream') {
      transport.sendJSON({
        op: 6,
        d: { requestType: 'ToggleStream', requestId: reqId }
      });
      return 'Toggled streaming';
    } else if (act === 'toggle_record' || act === 'record') {
      transport.sendJSON({
        op: 6,
        d: { requestType: 'ToggleRecord', requestId: reqId }
      });
      return 'Toggled recording';
    } else if (act === 'mute_input' || act === 'toggle_mute' || act === 'mute') {
      var input = params.input_name || params.input || params.value || params.param || 'Mic/Aux';
      transport.sendJSON({
        op: 6,
        d: {
          requestType: 'ToggleInputMute',
          requestId: reqId,
          requestData: { inputName: input }
        }
      });
      return 'Toggled mute for ' + input;
    }
    return 'Executed action ' + actionId;
  },

  onHeartbeat: function(transport) {
    if (this.identified) {
      transport.sendJSON({
        op: 6,
        d: {
          requestType: 'GetStreamStatus',
          requestId: 'hb_stream'
        }
      });
    }
  }
};
